// Regression test for: Shipping charged ($5) even though subtotal exceeds $50 free-shipping threshold
// Generated by WebProbe gen-tests from 2026-11-11T19-26-42-760Z, report #7.
// It failed with the bug and passed on the clean site. Edit freely; promote-tests won't overwrite it.

import { test, expect } from "@playwright/test";

test("checkout gives free shipping when subtotal exceeds $50", async ({ page }) => {
  const pageErrors: Error[] = [];
  page.on("pageerror", (err) => pageErrors.push(err));

  // Build the cart: one Ceramic Mug, one Desk Lamp, one Dot Grid Notebook.
  await page.goto("/product/mug");
  await page.getByRole("button", { name: "Add to cart" }).click();

  await page.goto("/product/lamp");
  await page.getByRole("button", { name: "Add to cart" }).click();

  await page.goto("/product/notebook");
  await page.getByRole("button", { name: "Add to cart" }).click();

  // Raise the mug quantity to 3 in the cart.
  await page.goto("/cart");
  const mugQty = page.getByRole("spinbutton", { name: "Quantity of Ceramic Mug" });
  await mugQty.fill("3");
  await mugQty.press("Tab");
  await expect(page.getByRole("heading", { name: "Total: $90.00" })).toBeVisible();

  await page.getByRole("link", { name: "Checkout" }).click();
  await expect(page.getByRole("heading", { name: "Checkout" })).toBeVisible();

  // Subtotal is $90, which is above the $50 threshold, so shipping must be free.
  const subtotalRow = page.getByRole("row").filter({ hasText: "Subtotal" });
  await expect(subtotalRow).toContainText("$90.00");

  const shippingRow = page.getByRole("row").filter({ hasText: "Shipping" });
  await expect(shippingRow).toContainText(/\$0\.00|Free/);
  await expect(shippingRow).not.toContainText("$5.00");

  const totalRow = page.getByRole("row").filter({ hasText: "Order total" });
  await expect(totalRow).toContainText("$90.00");
  await expect(totalRow).not.toContainText("$95.00");

  expect(pageErrors).toEqual([]);
});
